export function chunkIds(ids: string[], size: number): string[][] {
  if (!ids.length || size <= 0) return [];
  const chunks: string[][] = [];
  for (let i = 0; i < ids.length; i += size) {
    chunks.push(ids.slice(i, i + size));
  }
  return chunks;
}
